* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, sans-serif; font-size: 16px; background: #17252b; color: #202d32; }
body { min-height: 100vh; margin: 0; display: grid; place-items: center; padding: 24px 16px; background: radial-gradient(ellipse at 50% 0%, #31515a 0, #17252b 68%); }
.calculator { width: min(100%, 520px); padding: 30px; border: 3px solid #202d32; border-radius: 12px; background: #f1eddf; box-shadow: 8px 8px 0 #101a1e, 0 18px 48px #101a1e88; }
.header { margin-bottom: 24px; }
.eyebrow { margin: 0 0 8px; color: #46766e; font-size: .8rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(1.7rem, 7vw, 2.2rem); line-height: 1.15; }
.subtitle { margin: 8px 0 0; color: #536267; }
.stack-panel { min-height: 148px; padding: 16px; border: 2px solid #202d32; border-radius: 8px; background: #d9e5d5; box-shadow: inset 0 3px 0 #bdd0c1; }
.stack-heading { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
h2 { margin: 0; font-size: 1rem; }
#stack-count { color: #536267; font-size: .9rem; }
.stack { display: flex; flex-direction: column-reverse; gap: 7px; max-height: 190px; margin: 12px 0 0; padding: 0; overflow: auto; list-style: none; }
.stack li { display: flex; justify-content: space-between; align-items: center; padding: 9px 11px; border: 1px solid #9eb9a7; border-radius: 5px; background: #f8f7ee; font-variant-numeric: tabular-nums; }
.stack li span:first-child { color: #64806e; font-size: .78rem; font-weight: 700; text-transform: uppercase; }
.stack li strong { font-size: 1.1rem; }
.empty-note { margin: 20px 0 4px; color: #536267; text-align: center; }
.empty-note[hidden] { display: none !important; }
.message { min-height: 24px; margin: 12px 2px; color: #46766e; font-weight: 700; }
.message.error { color: #a34737; }
.keypad { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.number-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.side-keys { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
button { min-height: 52px; border: 2px solid #202d32; border-radius: 6px; background: #f8f7ee; color: #202d32; font: inherit; font-size: 1.15rem; font-weight: 750; cursor: pointer; box-shadow: 0 3px 0 #202d32; transition: transform .08s ease, background .12s ease, box-shadow .08s ease; }
button:hover { background: #d9e5d5; }
button:focus-visible { outline: 3px solid #bd744c; outline-offset: 3px; }
button:active { transform: translateY(3px); box-shadow: 0 0 0 #202d32; }
.number-grid .zero { grid-column: span 2; }
.side-keys button[data-op] { background: #46766e; color: #fff; }
.side-keys button[data-op]:hover { background: #355f58; }
.side-keys .enter { grid-column: span 2; background: #bd744c; color: #fff; }
.side-keys .enter:hover { background: #a8613d; }
.side-keys .clear { grid-column: span 2; background: #e4d9c8; }
footer { margin-top: 20px; color: #536267; font-size: .82rem; text-align: center; line-height: 1.5; }
@media (max-width: 420px) { .calculator { padding: 22px 18px; } .keypad { gap: 9px; } .number-grid, .side-keys { gap: 7px; } button { min-height: 48px; } }

const stack = [];
const stackList = document.querySelector('#stack');
const count = document.querySelector('#stack-count');
const emptyNote = document.querySelector('#empty-note');
const message = document.querySelector('#message');

function announce(text, error = false) {
  message.textContent = text;
  message.classList.toggle('error', error);
}

function render() {
  stackList.replaceChildren(...stack.map((value, index) => {
    const item = document.createElement('li');
    const label = document.createElement('span');
    const number = document.createElement('strong');
    label.textContent = index === stack.length - 1 ? 'Top' : `#${index + 1}`;
    number.textContent = format(value);
    item.append(label, number);
    return item;
  }));
  count.textContent = `${stack.length} ${stack.length === 1 ? 'value' : 'values'}`;
  emptyNote.hidden = stack.length !== 0;
}

function format(value) {
  return Number.isInteger(value) ? String(value) : String(Number(value.toPrecision(10)));
}

function push(value) {
  stack.push(value);
  render();
  announce(`${format(value)} pushed onto the stack.`);
}

function operate(operator) {
  if (stack.length < 2) {
    announce(`Need two values to ${operator}.`, true);
    return;
  }
  const right = stack.pop();
  const left = stack.pop();
  const result = operator === '+' ? left + right
    : operator === '-' ? left - right
    : operator === '*' ? left * right
    : left / right;
  push(result);
  announce(`${format(left)} ${operator} ${format(right)} = ${format(result)}.`);
}

function addDigit(digit) {
  if (digit === '.' && stack.length && !Number.isInteger(stack[stack.length - 1])) {
    announce('Decimal values are entered as whole numbers for this keypad.', true);
    return;
  }
  push(digit === '.' ? 0 : Number(digit));
}

document.querySelectorAll('[data-number]').forEach(button => {
  button.addEventListener('click', () => addDigit(button.dataset.number));
});
document.querySelectorAll('[data-op]').forEach(button => {
  button.addEventListener('click', () => operate(button.dataset.op));
});
document.querySelector('#enter').addEventListener('click', () => {
  if (!stack.length) announce('Enter a number first.', true);
  else announce('Stack is ready.');
});
document.querySelector('#clear').addEventListener('click', () => {
  stack.length = 0;
  render();
  announce('Stack cleared.');
});

document.addEventListener('keydown', event => {
  if (/^[0-9.]$/.test(event.key)) addDigit(event.key);
  else if (['+', '-', '*', '/'].includes(event.key)) operate(event.key);
  else if (event.key === 'Enter') {
    event.preventDefault();
    if (!stack.length) announce('Enter a number first.', true);
    else announce('Stack is ready.');
  } else if (event.key === 'Escape') {
    stack.length = 0;
    render();
    announce('Stack cleared.');
  }
});

render();
